/* 0x552200, the stage-0 start handler of the master exam offer event 0x7f (its run handler he_RunExamOffer): the
   stage 0, the due clock now with the hour 9 + random(3) and the minute random(4) * 15, no answer yet */
void he_StartExamOffer(int ev)
{
    AIJOB *e = (AIJOB *)ev;
    HEEXAMOFFER *o = (HEEXAMOFFER *)ev;
    int r;

    e->stage = 0;
    e->end = ai_Time;
    e->end.hour = (unsigned short)(util_Random(3) + 9);
    r = (unsigned short)util_Random(4);
    o->accepted = 0;
    e->end.min = r * 15;
}
/* 0x552270, the run handler of the exam offer event 0x7f (its alloc handler he_StartExamOffer): stage 0 asks the
   character (+0xac) the master exam question, the message 0x7e that becomes he_RunExamQuestion's event (the
   character, this event's id, due in two hours, flags 9), and waits 8 hours (stage 1); then, accepted (he_RunExamQuestion
   set accepted), the character loses (1 - skill 3) / 2 of its health (the skill at least 0.1), the own player is
   paid 6% of its worth times the skill (cm_SendMoveGoodsUnchecked) and the character is told 0x10ba, else 0x10bb;
   then, as any other stage, the event is freed */
void he_RunExamOffer(int ev)
{
    AIJOB *e = (AIJOB *)ev;
    float skill;
    int worth, pay;
    HEEXAMMSG m;
    char text[0x800];
    AICHAR *c;

    if (e->stage < 0 || e->stage > 1) {
        he_FreeEvent((int *)ev);
        return;
    }
    if (e->stage == 0) {
        memset(&m, 0, sizeof(m));
        m.msg.time = ai_Time;
        m.msg.to = ((HEEXAMOFFER *)e)->chr;
        m.q.chr = ((HEEXAMOFFER *)e)->chr;
        m.msg.type = 0x7e;
        m.msg.fromId = -1;
        m.msg.flags = 9;
        m.q.examId = e->id;
        m.q.due = ai_Time;
        gm_AddTime(&m.q.due, 2, 0, 0);
        cm_SendLongMessage((char *)&m);
        e->stage = 1;
        e->end = ai_Time;
        gm_AddTime(&e->end, 8, 0, 0);
    } else if (e->stage == 1) {
        if (((HEEXAMOFFER *)e)->accepted != 0) {
            c = &ai_CharsT[e->chr];
            if (gm_GetSkill((char *)c, 3) > 0.1f)
                skill = gm_GetSkill((char *)c, 3);
            else
                skill = 0.1f;
            worth = gm_GetWorth(c->id);
            gm_AddHealth(c->id, -(int)((int)gm_CharacterHealth(c) * ((ai_FloatOne - skill) * 0.5f)));
            pay = (int)(worth * skill * 0.06f);
            cm_SendMoveGoodsUnchecked(((HEEXAMOFFER *)e)->chr, -1, ai_OwnPlayer, pay);
            txt_Format(text, 0x10ba, pay);
            he_ShowNews(((HEEXAMOFFER *)e)->chr, -1, text, 0x20, 0x5fd, ch_EmptyName);
        } else {
            txt_Format(text, 0x10bb);
            he_ShowNews(((HEEXAMOFFER *)e)->chr, -1, text, 0x20, 0x5fd, ch_EmptyName);
        }
        he_FreeEvent((int *)ev);
    }
}
/* 0x5524e0, the stage-0 start handler shared by the events 0x80 and 0x81 (the conversion): unless its option 4
   says it is not started yet, the due clock is a copy of the start clock and the event is posted at once (its
   cm slot kept in exSlot) */

void he_StartDue(int ev)
{
    AIJOB *e = (AIJOB *)ev;

    if ((e->opts & 4) == 0) {
        e->end = e->start;
        e->exSlot = cm_SendExSetHE(0, ev);
    }
}

void cm_BeginFieldBlock(char *o, int id);
int cm_AddFieldDelta(unsigned char size, unsigned char n, unsigned short field, void *v);
int cm_SendFieldDeltas(void);

/* 0x552520, the run handler of the delay event 0x80 (its start handler he_StartDue): a negative stage or no day
   left (HEDELAY.days) frees the record; a record with the option 4 does nothing; else a day is counted off and the
   event is posted a day later (its cm slot kept in exSlot) */
void he_RunDelay(int ev)
{
    AIJOB *e = (AIJOB *)ev;
    HEDELAY *d = (HEDELAY *)ev;

    if (e->stage < 0 || d->days <= 0) {
        he_FreeEvent((int *)ev);
        return;
    }
    if ((e->opts & 4) != 0)
        return;
    d->days = d->days - 1;
    e->end = ai_Time;
    gm_AddTime(&e->end, 0x18, 0, 0);
    e->exSlot = cm_SendExSetHE(0, ev);
}
/* 0x5525a0, the run handler of the conversion event 0x81 (its alloc handler he_StartDue): while it has rounds and
   characters left, each round (a day apart) turns up to n = min(left, ceil(left + rounds)) characters whose b00c
   (the kind the person tooltip names) is `from` to the other kind (1 - from, a field delta of AICHAR +0xc), walking
   the 0x300 characters from a random one (ids in use, kinds up to 4); found fewer than n, it tries again 5 minutes
   later. A negative stage, no rounds or no characters left free the event, flag 4 of opts holds it
   @deep read whole against the original and fixed the meaning (ceil not sqrt, n = min(left, ceil(left +
   rounds)) as one double expression, the field value 1 - from computed first, util_RandomU start, typed
   HECONVERT words). Left, allocation only: the original keeps cnt in a frame slot (inc dword ptr
   [esp+0x10], cmp [esp+0x10], ebx) and left in ebp (dec ebp; test ebp, ebp), ours keeps cnt in ebx and
   left in the dead parameter slot (dec dword ptr [esp+0x20]); hence frame 0xc vs 0x10, 526 vs 538 bytes,
   the permuted registers (n ebx | ebp, ring esi | edi, ev edi | esi) and the original's push ebp (left, 0
   after the loop) for gm_AddTime's zeros where ours pushes 0. A do / while form of the loop tried, no
   change. The prover stops there (it reads left as 0x2ff on its path). */
void he_RunConversion(int ev)
{
    AIJOB *e = (AIJOB *)ev;
    HECONVERT *cv = (HECONVERT *)ev;
    int cnt = 0;
    int to = 1 - cv->from;
    int n, ring, left;
    AICHAR *c;

    if (e->stage < 0 || cv->rounds <= 0 || cv->left <= 0) {
        he_FreeEvent((int *)ev);
        return;
    }
    if ((e->opts & 4) != 0)
        return;
    n = (int)((double)cv->left < ceil((double)(cv->left + cv->rounds)) ? (double)cv->left : ceil((double)(cv->rounds + cv->left)));
    ring = util_RandomU(0x300);
    for (left = 0x300; left != 0; left--) {
        if (cnt >= n)
            break;
        c = &ai_CharsT[ring];
        if (c->id != 0xffff && c->kind <= 4 && c->b00c == cv->from) {
            cm_BeginFieldBlock((char *)c, c->netId);
            cm_AddFieldDelta(1, 1, 0xc, &to);
            cm_SendFieldDeltas();
            cnt++;
        }
        ring = (ring + 1) % 0x300;
    }
    if (cnt < n) {
        e->end = ai_Time;
        gm_AddTime(&e->end, 0, 5, 0);
        e->exSlot = cm_SendExSetHE(-1, ev);
        return;
    }
    cv->rounds--;
    cv->left -= n;
    e->end = ai_Time;
    gm_AddTime(&e->end, 0x18, 0, 0);
    e->exSlot = cm_SendExSetHE(0, ev);
}
/* 0x5527c0, the stage-0 start handler of the skill-bonus event 0x82 (its run handler 0x552820; GMSKILLEV in
   f3gm_types.h holds the bonus words): unless its option 4 says it is not started yet, the due clock is now + the
   bonus's duration (HESKILLBONUS.hours) and the event is posted at once (its cm slot kept in exSlot) */

void he_StartSkillBonus(int ev)
{
    AIJOB *e = (AIJOB *)ev;
    HESKILLBONUS *b = (HESKILLBONUS *)ev;

    if ((e->opts & 4) == 0) {
        e->end = ai_Time;
        gm_AddTime(&e->end, b->hours, 0, 0);
        e->exSlot = cm_SendExSetHE(0, ev);
    }
}
/* 0x552820, the run handler of the skill-bonus event 0x82 (its start handler he_StartSkillBonus): the states -1 / -2
   free the record; else, unless its option 4 says it is not started yet, the bonus is over: the due clock is set to
   now and the event is ended with the cm slot handle -1 (the next call frees it) */

void he_RunSkillBonus(int ev)
{
    AIJOB *e = (AIJOB *)ev;
    int st = e->stage;

    if (st == -1 || st == -2) {
        he_FreeEvent((int *)ev);
        return;
    }
    if ((e->opts & 4) != 0)
        return;
    e->end = ai_Time;
    e->exSlot = cm_SendExSetHE(-1, ev);
}
/* 0x552880, the start handler of the applicants event 0x86 (its run handler he_RunApplicants): unless its option 4
   says it is not started yet, the due clock is now at 17:00, moved a day on when it was already past 17:00; the
   office is unset, the highest kind looked at is 0x1b, both applicant handles are -1 and the event is posted at
   once (its cm slot kept in exSlot) */

void he_StartApplicants(int ev)
{
    AIJOB *e = (AIJOB *)ev;
    HEAPPLICANTS *a = (HEAPPLICANTS *)ev;

    if ((e->opts & 4) == 0) {
        e->end = ai_Time;
        if (e->end.hour >= 0x11)
            gm_AddTime(&e->end, 0x18, 0, 0);
        e->end.hour = 0x11;
        e->end.min = 0;
        a->office = 0;
        a->maxKind = 0x1b;
        a->applicant[0] = -1;
        a->applicant[1] = -1;
        e->exSlot = cm_SendExSetHE(0, ev);
    }
}

int cm_GetSlotValue(int h);
int amt_InitApplicant(char *c, int k);
int amt_GetOpenOffice(int k);
int amt_CreateApplicant(int k);

/* 0x552920, the run handler of the applicants event 0x86 (its alloc handler he_StartApplicants): stage -1 / -2 free it,
   flag 4 of opts or a pending post (exSlot) holds it. Stage 0 asks for the highest office kind up to maxKind that is
   open for one more applicant (amt_GetOpenOffice) and creates two applicants for it (amt_CreateApplicant; the second
   only two times in three); no kind (or maxKind 0): it starts over a day later at 17 o'clock with maxKind 0x1b.
   Stage 1 waits for both created characters (cm_GetSlotState 1: initialised as applicants, amt_InitApplicant; 2: gone)
   and when both are done posts the event 5 minutes later; else, as after stage 0, the event is posted again now
   (cm_SendExSetHE 1) */
void he_RunApplicants(int ev)
{
    AIJOB *e = (AIJOB *)ev;
    HEAPPLICANTS *ap = (HEAPPLICANTS *)ev;
    int done, r;
    char *c;

    if (e->stage == -1 || e->stage == -2) {
        he_FreeEvent((int *)ev);
        return;
    }
    if ((e->opts & 4) != 0)
        return;
    if (e->exSlot != -1 && cm_GetSlotState(e->exSlot) == 0)
        return;
    e->exSlot = -1;
    switch (e->stage) {
    case 0:
        if (ap->maxKind == 0) {
            gm_AddTime(&e->end, 0x18, 0, 0);
            e->end.hour = 0x11;
            e->end.min = 0;
            ap->office = 0;
            ap->maxKind = 0x1b;
            ap->applicant[0] = -1;
            ap->applicant[1] = -1;
            e->exSlot = cm_SendExSetHE(0, ev);
            return;
        }
        ap->office = amt_GetOpenOffice(ap->maxKind);
        if (ap->office == 0) {
            gm_AddTime(&e->end, 0x18, 0, 0);
            e->end.hour = 0x11;
            e->end.min = 0;
            ap->office = 0;
            ap->maxKind = 0x1b;
            ap->applicant[0] = -1;
            ap->applicant[1] = -1;
            e->exSlot = cm_SendExSetHE(0, ev);
            return;
        }
        ap->applicant[0] = amt_CreateApplicant(ap->office);
        ap->applicant[1] = (unsigned short)util_Random(3) != 0 ? amt_CreateApplicant(ap->office) : -1;
        break;
    case 1:
        done = 0;
        if (ap->applicant[0] == -1) {
            done = 1;
        } else {
            r = cm_GetSlotState(ap->applicant[0]);
            if (r == 1) {
                done = r;
                c = (char *)cm_GetSlotValue(ap->applicant[0]);
                amt_InitApplicant(c, ap->office);
                ap->applicant[0] = -1;
            } else if (r == 2) {
                ap->applicant[0] = -1;
                done = 1;
            }
        }
        if (ap->applicant[1] == -1) {
            done++;
        } else {
            r = cm_GetSlotState(ap->applicant[1]);
            if (r == 1) {
                done++;
                c = (char *)cm_GetSlotValue(ap->applicant[1]);
                amt_InitApplicant(c, ap->office);
                ap->applicant[1] = -1;
            } else if (r == 2) {
                ap->applicant[1] = -1;
                done++;
            }
        }
        if (done == 2) {
            e->end = ai_Time;
            gm_AddTime(&e->end, 0, 5, 0);
            e->exSlot = cm_SendExSetHE(0, ev);
            return;
        }
        break;
    default:
        return;
    }
    e->end = ai_Time;
    e->exSlot = cm_SendExSetHE(1, ev);
}

int ai_TutorialSetHost();
int ai_TutorialOpenIntro();
int ai_TutorialTick();
int ai_TutorialCloseIntro();
void ai_TutorialClearHost(void);
void sv_PopTo(int v);
